package com.example.bodega.reporte.service;
import com.example.bodega.common.exception.BusinessException; import com.example.bodega.producto.repository.ProductoRepository; import com.example.bodega.reporte.dto.*; import com.example.bodega.venta.enums.EstadoVenta; import com.example.bodega.venta.repository.VentaRepository;
import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal; import java.time.*; import java.util.*;
@Service @RequiredArgsConstructor @Transactional(readOnly=true)
public class ReporteService {private final VentaRepository ventas;private final ProductoRepository productos;
    public ReporteVentasResponse ventas(LocalDate desde,LocalDate hasta){if(hasta.isBefore(desde))throw new BusinessException("Rango de fechas invalido.");var lista=ventas.findByFechaBetween(desde.atStartOfDay(ZoneOffset.UTC).toInstant(),hasta.plusDays(1).atStartOfDay(ZoneOffset.UTC).toInstant()).stream().filter(v->v.getEstado()==EstadoVenta.COMPLETADA).toList();Map<String,BigDecimal> porMetodo=new TreeMap<>();BigDecimal total=BigDecimal.ZERO;for(var v:lista){total=total.add(v.getTotal());porMetodo.merge(v.getMetodoPago().name(),v.getTotal(),BigDecimal::add);}return new ReporteVentasResponse(desde,hasta,lista.size(),total,porMetodo);}
    public List<ProductoVendidoResponse> masVendidos(LocalDate desde,LocalDate hasta){Map<Long,ProductoVendidoResponse> result=new HashMap<>();for(var v:ventas.findByFechaBetween(desde.atStartOfDay(ZoneOffset.UTC).toInstant(),hasta.plusDays(1).atStartOfDay(ZoneOffset.UTC).toInstant()))if(v.getEstado()==EstadoVenta.COMPLETADA)for(var d:v.getDetalles()){var previo=result.get(d.getProducto().getId());result.put(d.getProducto().getId(),new ProductoVendidoResponse(d.getProducto().getId(),d.getProducto().getNombre(),d.getCantidad()+(previo==null?0:previo.cantidad())));}return result.values().stream().sorted(Comparator.comparingLong(ProductoVendidoResponse::cantidad).reversed()).toList();}
    public ValorInventarioResponse valorInventario(){return new ValorInventarioResponse(productos.findAll().stream().map(p->p.getPrecioCompra().multiply(BigDecimal.valueOf(p.getStockActual()))).reduce(BigDecimal.ZERO,BigDecimal::add));}
}
